pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {XBORNID} from "../src/XBORNID.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    XBORNID c;

    function setUp() public {
        c = new XBORNID();
    }

    function _run(uint256 sendValue) internal {
        sendValue = bound(sendValue, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendValue);
        uint256 before_balance;
        try c.balanceOf(address(this)) returns (uint256 __r) { before_balance = __r; } catch { return; }
        bool before_blacklisted;
        try c.blacklist(address(this)) returns (bool __r) { before_blacklisted = __r; } catch { return; }
        bool distributionFinishedBefore;
        try c.distributionFinished() returns (bool __r) { distributionFinishedBefore = __r; } catch { return; }
        uint256 totalRemainingBefore;
        try c.totalRemaining() returns (uint256 __r) { totalRemainingBefore = __r; } catch { return; }
        bool reverted;
        try c.getTokens{value: sendValue}() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 after_balance;
        try c.balanceOf(address(this)) returns (uint256 __r) { after_balance = __r; } catch { return; }
        bool after_blacklisted;
        try c.blacklist(address(this)) returns (bool __r) { after_blacklisted = __r; } catch { return; }
        bool distributionFinishedAfter;
        try c.distributionFinished() returns (bool __r) { distributionFinishedAfter = __r; } catch { return; }
        uint256 totalRemainingAfter;
        try c.totalRemaining() returns (uint256 __r) { totalRemainingAfter = __r; } catch { return; }
        assertTrue((reverted && after_balance == before_balance && after_blacklisted == before_blacklisted && totalRemainingAfter == totalRemainingBefore && distributionFinishedAfter == distributionFinishedBefore)
            ||
            // If not reverted: visible invariants hold
            (!reverted
                && after_balance >= before_balance
                // the increase equals the decrease in totalRemaining
                && (after_balance - before_balance == (totalRemainingBefore - totalRemainingAfter))
                // distributed amount cannot exceed previous remaining
                && (totalRemainingBefore >= totalRemainingAfter)
                // if we gained tokens (>0) then we must be blacklisted after the call
                && ((after_balance - before_balance == 0) || after_blacklisted == true)
                // distributionFinished can only go from false to true, not revert to false
                && ( !(distributionFinishedBefore == true && distributionFinishedAfter == false) )
            ));
    }

    function testFuzz_run(uint256 sendValue) public {
        _run(sendValue);
    }

    receive() external payable {}
}
